import java.util.List;

abstract class Employee {
    protected final String id;
    protected final String name;
    protected final double baseSalary;

    protected Employee(String id, String name, double baseSalary) {
        this.id = id;
        this.name = name;
        this.baseSalary = baseSalary;
    }

    public abstract double calculateSalary();

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}

class Developer extends Employee {
    private final double overtimeHours;
    private final double bonusRate;

    public Developer(String id, String name, double baseSalary,
                      double overtimeHours, double bonusRate) {
        super(id, name, baseSalary);
        this.overtimeHours = overtimeHours;
        this.bonusRate = bonusRate;
    }

    @Override
    public double calculateSalary() {
        return baseSalary + (overtimeHours * bonusRate);
    }
}

class Manager extends Employee {
    private final int teamSize;
    private final double kpiMultiplier;

    public Manager(String id, String name, double baseSalary,
                    int teamSize, double kpiMultiplier) {
        super(id, name, baseSalary);
        this.teamSize = teamSize;
        this.kpiMultiplier = kpiMultiplier;
    }

    @Override
    public double calculateSalary() {
        return (baseSalary + teamSize * 200.0) * kpiMultiplier;
    }
}

record EmployeeDTO(String id, String name, double totalSalary) {
}

class PayrollService {
    public List<EmployeeDTO> runPayroll(List<Employee> employees) {
        return employees.stream()
                .map(e -> new EmployeeDTO(e.getId(), e.getName(), e.calculateSalary()))
                .toList();
    }
}

