@Test
void runPayroll_mixedEmployees_returnsCorrectTotals() {
    Employee dev = new Developer("E1", "An", 10_000_000, 10, 50_000);
    Employee mgr = new Manager("E2", "Binh", 20_000_000, 5, 1.1);
    PayrollService service = new PayrollService();

    List<EmployeeDTO> result = service.runPayroll(List.of(dev, mgr));

    assertEquals(2, result.size());
    assertEquals(10_500_000.0, result.get(0).totalSalary());
    assertEquals(22_000_000.0, result.get(1).totalSalary());
}
